def transform(grid):
    a=[row[1:-1] for row in grid[2:-1]]
    cols=[c for c in range(len(a[0])) if any(row[c]!=8 for row in a)]
    runs=[]
    for c in cols:
        if not runs or c>runs[-1][-1]+1: runs.append([c])
        else: runs[-1].append(c)
    objects=[]
    row_major = grid[0][1] == 1
    for run in runs:
        active=[r for r,row in enumerate(a) if any(row[c]!=8 for c in run)]
        segments=[]
        for r in active:
            if not segments or r>segments[-1][-1]+1: segments.append([r])
            else: segments[-1].append(r)
        for seg in segments:
            counts={}
            for r in seg:
                for c in run:
                    if a[r][c]!=8: counts[a[r][c]]=counts.get(a[r][c],0)+1
            groups=[]
            for r in seg:
                color=max((a[r][c] for c in run if a[r][c]!=8),key=lambda x:counts[x])
                if not groups or color!=groups[-1][1]: groups.append(([r],color))
                else: groups[-1][0].append(r)
            obs=[[[a[r][c] for c in run] for r in rs] for rs,color in groups]
        if row_major:
            for ob in obs: objects.append((seg[0]+sum(len(x[0]) for x in groups[:obs.index(ob)]),ob))
        else: objects += [(0,ob) for ob in obs]
    if row_major: objects.sort(key=lambda x:x[0])
    rotated=[list(x) for _,obj in objects for x in list(zip(*obj))[::-1]]
    width=max(max(map(len,rotated)),max(map(len,runs)))
    return [[8]*((width-len(row))//2)+list(row)+[8]*(width-len(row)-(width-len(row))//2) for row in rotated]

